scwin.checktype1 = function() {
    return typeof WebSquare.wUnit.getObjById('widgetContainer1_widget0');
}
scwin.checktype2 = function() {
    return typeof WebSquare.wUnit.getObjById('widgetContainer1_widget1');
}
scwin.checktype3 = function() {
    return typeof WebSquare.wUnit.getObjById('widgetContainer1_widget2');
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Script 탭에서 widgetContainer1.addWidgets 에 widget0 부분을 확인한다.
    //1. On the Script tab, check widget0 for widgetContainer1.addWidgets.
    //Verify 1. Review comments
    //Test step 2 . widgetContainer1.addWidgets 에 widget1 부분을 확인한다.
    //2. Check widget1 in widgetContainer1.addWidgets.
    //Verify 2. Confirm comments
    //Test step 3. widgetContainer1.addWidgets 에 widget2 부분을 확인한다.
    //3. Check widget2 in widgetContainer1.addWidgets.
    //Verify 3. Confirm comments
    //Test step 4. 브라우저에서 확인한다.
    //4. Check in the browser.
    WebSquare.wUnit.addCommand("assert", "scwin.checktype1()", "object");
    WebSquare.wUnit.addCommand("assert", "scwin.checktype2()", "object");
    WebSquare.wUnit.addCommand("assert", "scwin.checktype3()", "object");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
